/**
 * Claim-type configuration lookup.
 * All data comes from input.questionDefs (question-definitions.json).
 * To change questions or required documents per type, edit question-definitions.json only.
 *
 * Input:  { claimType: string, questionDefs: { MOTOR: {...}, MEDICAL: {...}, ... } }
 * Output: { claimType, questions: QuestionDef[], requiredDocuments: string[] }
 */
const handler = (input) => {
  const defs   = input.questionDefs || {};
  const config = defs[input.claimType];
  if (!config) throw new Error('Unknown claim type: ' + input.claimType);

  return {
    claimType: input.claimType,
    questions: (config.questions || []).map(q => ({
      questionId:   q.id,
      questionText: q.label,
      fieldType:    q.type
    })),
    requiredDocuments: (config.requiredDocuments || []).map(d => d.type)
  };
};
